 w.HTMLElement.prototype.setPointerCapture=function(){};Object.defineProperty(w.HTMLElement.prototype,'clientWidth',{get(){return this.classList.contains('table-wrap')?640:0;}});w.HTMLElement.prototype.getBoundingClientRect=function(){return {width:parseFloat(this.style.width)||0,x:0,y:0,top:0,left:0,bottom:30,right:640,height:30};};
