 const drag=async(key,delta)=>{const th=d.querySelector(`.table-wrap th[data-column=${key}]`),handle=th.querySelector('.column-resize'),before=parseFloat(th.style.width);handle.dispatchEvent(new w.MouseEvent('pointerdown',{clientX:100,bubbles:true,cancelable:true}));handle.dispatchEvent(new w.MouseEvent('pointermove',{clientX:100+delta,bubbles:true}));assert.equal(parseFloat(th.style.width),before+delta);handle.dispatchEvent(new w.MouseEvent('pointerup',{bubbles:true}));await flush();assert.equal(parseFloat(d.querySelector(`.table-wrap th[data-column=${key}]`).style.width),before+delta);};
