  await drag('title',25);
  d.querySelector('.table-wrap th[data-column=number]').dispatchEvent(new w.MouseEvent('contextmenu',{bubbles:true,cancelable:true}));[...d.querySelectorAll('.column-alignment-item')].find(b=>b.textContent==='Center').click();await flush();assert.equal(d.querySelector('#tracks td[data-column=number]').style.textAlign,'center');assert.equal(state.settings.columnsByView.tracks.find(c=>c.key==='number').align,'center');
