 const state={libraries:[{id:'l',name:'Music'}],playlists:[],settings:{lastView:'tracks',libraryOpening:'none',artistGrouping:'artist'},tracks:['a','b','c'].map((id,i)=>({id,libraryId:'l',title:id,artist:'Artist '+i,albumArtist:'Artist '+i,album:'Album '+i,track:1,duration:60,codec:'MP3'}))};let edited=[],renamed=[],rated=[];
 w.HTMLMediaElement.prototype.pause=()=>{};w.HTMLMediaElement.prototype.load=()=>{};
 w.localtone={load:async()=>snapshot(state),onProgress(){},settings:async p=>p,readTagsBatch:async ids=>{edited=[...ids];return ids.map(id=>({id,token:'token',values:{title:id,track:'1'},extras:[]}));},previewFileNames:async ids=>{renamed=[...ids];return {token:'token',affected:ids,count:ids.length,items:[]};},rate:async(id,value)=>{rated.push([id,value]);return {...snapshot(state),ratings:{[id]:value}};}};
 const key=(key,extra={})=>d.activeElement.dispatchEvent(new w.KeyboardEvent('keydown',{key,bubbles:true,cancelable:true,...extra}));
