test('playlist double-click starts randomly in the full queue; Backspace clears without losing navigation; text colors preview, save and reset',async()=>{
 const dom=new JSDOM(html,{runScripts:'outside-only'}),w=dom.window,d=w.document;
 Object.assign(w,{createSettingsHelp,createDuplicatesDialog,createFileNamingDialog},core,browse,interactions,{structuredClone,designDefaults,appearanceDefaults,createSettingsWrites,createTagEditor,createPlaylistEditor,createLastfmSettings,createDialogCoordinator,createSettingsTabs,createBrowseSelection,createPlaybackQueue,createWindowPresentation,createAudioOutputSettings,mountVirtualTracks,createIcons,normalizeMenu,shortcutDefaults,createQueueViewCache,queuePage,createNameDialog,ListenTracker,waveformPath});
 for(const dialog of d.querySelectorAll('dialog')){dialog.showModal=()=>dialog.setAttribute('open','');dialog.close=()=>{dialog.removeAttribute('open');dialog.dispatchEvent(new w.Event('close'));};}
 const tracks=Array.from({length:6},(_,i)=>({id:String(i),libraryId:'l',title:'Track '+i,artist:['A','B','C'][Math.floor(i/2)],album:'Album '+Math.floor(i/2),albumArtist:['A','B','C'][Math.floor(i/2)],year:2009,artistPath:'Album '+Math.floor(i/2)+'/'+i+'.mp3',duration:60,track:i%2+1,codec:'MP3'}));
 const state={libraries:[{id:'l',name:'Library'}],playlists:[{id:'p',name:'Mix',trackIds:['5','4','3','2','1','0']},{id:'empty',name:'Empty',trackIds:[]}],tracks,settings:{defaultView:'tracks',albumExpansion:'collapsed'}},patches=[],actions=[];
 w.Math.random=()=>.5;w.HTMLMediaElement.prototype.play=async()=>{};
 w.localtone={load:async()=>snapshot(state),onProgress(){},windowAction:async action=>actions.push(action),settings:async patch=>{patches.push(patch);Object.assign(state.settings,patch);return patch;}};
 const key=(value,extra={},target=d.activeElement)=>target.dispatchEvent(new w.KeyboardEvent('keydown',{key:value,bubbles:true,cancelable:true,...extra}));
 try{
  await w.eval(`(async()=>{${source}\nwindow.probe=()=>({albumFocus:selection.albumFocus,coverFocus:selection.coverFocus,albums:[...selection.albums],pane:selection.pane,artist:selection.artists.current,artists:[...selection.artists],tracks:[...selection.tracks],current:selection.tracks.current,queue:[...playback.queue],cursor:playback.cursor,playing:currentTrack()?.id,shuffle,repeat});})()`);
  const probe=()=>JSON.parse(JSON.stringify(w.probe()));
  d.querySelector('#playlists button').dispatchEvent(new w.MouseEvent('dblclick',{bubbles:true}));
  assert.deepEqual(probe().queue,['5','4','3','2','1','0']);assert.equal(probe().playing,'2');assert.equal(probe().cursor,3);
  d.getElementById('next-track').click();assert.equal(probe().playing,'1');
  d.getElementById('shuffle').click();await flush();
  d.querySelector('#playlists button').dispatchEvent(new w.MouseEvent('dblclick',{bubbles:true}));
  assert.equal(probe().playing,'2');assert.equal(probe().cursor,0);assert.equal(probe().shuffle,true);assert.deepEqual([...probe().queue].sort(),['0','1','2','3','4','5']);
  d.querySelectorAll('#playlists button')[1].dispatchEvent(new w.MouseEvent('dblclick',{bubbles:true}));assert.equal(probe().playing,'2');
  d.querySelector('#libraries button').click();d.getElementById('view-tracks').click();
  let artists=[...d.querySelectorAll('#artist-list button')];artists[1].click();artists=[...d.querySelectorAll('#artist-list button')];artists[2].dispatchEvent(new w.MouseEvent('click',{shiftKey:true,bubbles:true}));
  const scroll=d.querySelector('.content-scroll');scroll.scrollTop=120;
  key('Backspace',{},d.body);assert.equal(probe().pane,'artists');assert.equal(probe().artist,null);assert.equal(probe().artists.length,0);assert.equal(d.querySelectorAll('#artist-list .active').length,0);assert.equal(scroll.scrollTop,120);
  key('ArrowDown');assert.equal(probe().artist,'A');
  key('Backspace');key('ArrowDown');assert.equal(probe().artist,'B');key('Backspace');
  d.getElementById('view-tracks').click();let rows=[...d.querySelectorAll('#tracks tr')];rows[2].click();rows[4].dispatchEvent(new w.MouseEvent('click',{shiftKey:true,bubbles:true}));scroll.scrollTop=160;
  key('Backspace',{},d.body);assert.equal(probe().pane,'tracks');assert.deepEqual(probe().tracks,[]);assert.equal(probe().current,null);assert.equal(scroll.scrollTop,160);assert.equal(d.querySelectorAll('#tracks .selected').length,0);
  key('Tab');key('Tab');assert.deepEqual(probe().tracks,[]);key('ArrowDown');assert.deepEqual(probe().tracks,['5']);
  d.getElementById('view-albums').click();key('ArrowDown',{},d.body);key('ArrowDown',{shiftKey:true},d.body);assert.equal(probe().albums.length,2);
  const albumKeys=[...d.querySelectorAll('.album-section')].map(n=>n.dataset.albumKey),lastAlbum=probe().albumFocus;
  key('Backspace',{},d.body);assert.deepEqual(probe().albums,[]);assert.equal(probe().albumFocus,null);key('ArrowDown');assert.equal(probe().albumFocus,albumKeys[(albumKeys.indexOf(lastAlbum)+1)%albumKeys.length]);
  d.getElementById('view-covers').click();key('ArrowRight',{},d.body);key('ArrowRight',{},d.body);key('ArrowRight',{shiftKey:true},d.body);assert.ok(probe().albums.length>1);
  const coverKeys=[...d.querySelectorAll('.album-cover-button')].map(n=>n.dataset.albumKey),lastCover=probe().coverFocus;
  key('Backspace',{},d.body);assert.deepEqual(probe().albums,[]);assert.equal(probe().coverFocus,null);key('ArrowLeft');assert.equal(probe().coverFocus,coverKeys[(coverKeys.indexOf(lastCover)+coverKeys.length-1)%coverKeys.length]);

  key('q',{},d.body);assert.deepEqual(actions,[]);key('q',{ctrlKey:true},d.getElementById('search'));await flush();assert.deepEqual(actions,['quit']);key('q',{metaKey:true,repeat:true},d.body);assert.equal(actions.length,1);
  for(const [id,token,value] of [['primaryTextColor','--text-primary','#f0d0b0'],['secondaryTextColor','--text-muted','#8899aa']]){
   const input=d.getElementById('setting-'+id);input.value=value;input.dispatchEvent(new w.Event('input',{bubbles:true}));assert.equal(d.documentElement.style.getPropertyValue(token),value);input.dispatchEvent(new w.Event('change',{bubbles:true}));await flush();assert.equal(patches.at(-1)[id],value);
  }
  d.getElementById('reset-appearance').click();await flush();assert.equal(d.documentElement.style.getPropertyValue('--text-primary'),designDefaults.primaryTextColor);assert.equal(d.documentElement.style.getPropertyValue('--text-muted'),designDefaults.secondaryTextColor);
 }finally{w.close();}
});

